"""UMUD GASFAS-BENCH launcher (generated by kaggle/gasfas_bench_v31/build_kernel.py). GPL-3.0-only.

GasFasTrack: Drazan, Hullfish & Baxter 2019, Zenodo record 2598553 (CC BY 4.0). No competition test data is used.
"""
import base64, hashlib, json, os, subprocess, sys, time, zlib
from pathlib import Path

SMOKE = 3
STAGES = ['data', 'apo', 'ours', 'orient', 'measure']
SOURCES = {
"apo_fix_src.py": "",
"fo_src.py": "",
"tt_stages.py": "",
"gf_stages.py": "",
"prod/src/umud/__init__.py": "eNpTUlIKLcnMySzJTC1WSMsvUijJSFUI9Q11UfBOTE/PSVVIzkjMyUnNS0/VU1JS4uICAIQ/Dxw=",
"prod/src/umud/geometry_v2.py": "",
"prod/src/umud/shrinkage.py": "",
"prod/src/umud/metric.py": "",
"prod/src/umud/paths.py": "",
"prod/scripts/build_candidates.py": "",
"prod/scripts/build_candidates_v3.py": "",
"prod/scripts/eval_apo_v2.py": "",
"prod/scripts/eval_orient.py": "",
"prod/scripts/telemed_fl.py": ""
}
TMP = Path("/tmp/gf")
OUT = Path("/kaggle/working/gf_out")
T0 = time.time()


def say(msg):
    print(f"[launcher {time.time() - T0:7.1f}s] {msg}", flush=True)


def run(stage, keep_bank):
    env = dict(os.environ, GF_SMOKE=str(SMOKE), TT_SMOKE=str(SMOKE), GF_TMP=str(TMP), GF_OUT=str(OUT),
               PYTHONUNBUFFERED="1")
    if keep_bank:
        env["GF_KEEP_BANK"] = "1"
    (OUT / "logs").mkdir(parents=True, exist_ok=True)
    t = time.time()
    with (OUT / "logs" / f"{stage}.log").open("w", encoding="utf-8") as lf:
        p = subprocess.Popen([sys.executable, "-u", str(TMP / "gf_stages.py"), "--stage", stage], cwd=str(TMP),
                             stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
        for line in p.stdout:
            print(f"[{stage}] {line}", end="", flush=True)
            lf.write(line)
        code = p.wait()
    say(f"stage {stage} exit={code} {time.time() - t:.0f}s")
    return code


def main():
    TMP.mkdir(parents=True, exist_ok=True)
    OUT.mkdir(parents=True, exist_ok=True)
    shas = {}
    for name, blob in SOURCES.items():
        raw = zlib.decompress(base64.b64decode(blob))
        (TMP / name).parent.mkdir(parents=True, exist_ok=True)
        (TMP / name).write_bytes(raw)
        shas[name] = hashlib.sha256(raw).hexdigest()
    (OUT / "sources_sha256.json").write_text(json.dumps(shas, indent=1))
    say(f"python={sys.version.split()[0]} cpus={os.cpu_count()} smoke={SMOKE} stages={STAGES}")
    codes = {}
    for st in STAGES:
        failed_maps = any(codes.get(s, 0) != 0 for s in ("apo", "ours", "orient"))
        codes[st] = run(st, keep_bank=failed_maps)
        if st == "data" and codes[st] != 0:
            break
    (OUT / "exit_codes.json").write_text(json.dumps(codes))
    say(f"exit codes {codes}")
    for p in sorted(OUT.rglob("*")):
        if p.is_file() and p.parent.name != "qa":
            say(f"  {p.relative_to(OUT)} {p.stat().st_size / 1e6:.2f} MB")


main()
